!function(){"use strict";app.factory("aprobacionDocService",(function($injector){let url="AprobacionDocumento/",mS=$injector.get("mainService"),service={getAll:function(query){return mS.getData("get",url+"Get?json="+JSON.stringify(query),null,!0).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let aprobComprobantes=JSON.parse(response.payload)||[];return console.log(aprobComprobantes),aprobComprobantes.map(item=>({idAprob_Document:item.idAprob_Document,uniqueId:item.uniqueId,docOrigen:item.docOrigen,codDoc:item.codDoc,docOrigenDesc:item.docOrigenDesc,docDestinoDesc:item.docDestinoDesc,fechaEmision:item.fechaEmision,serie:item.serie,serieComprobante:item.serie,identificacionComprador:item.identificacionComprador,razonSocialComprador:item.razonSocialComprador,total:item.total,codEstado:item.codEstado,estado:item.estado,colorFila:item.colorFila}))}}).catch(error=>{throw console.log("Error get all Aprob. Docs service",error),error})},findById:function(id){return mS.getData("get",url+"GetId/"+id,null,!0).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let dataRepository=JSON.parse(response.payload),compRepository=dataRepository[0][0],clienteRepository=dataRepository[1][0],detalleRepository=dataRepository[2],historialRepository=dataRepository[3],infoAdicionalDocumento=dataRepository[4],datosAdicionalesArticulo=dataRepository[5],compMapper,clienteMapper;return{comprobante:{idAprob_Document:compRepository.idAprob_Document,uniqueId:compRepository.uniqueId,idTiempoCredito:compRepository.idTiempoCredito,idPuntoEmision:compRepository.idPuntoEmision,estab:compRepository.estab,ptoEmi:compRepository.ptoEmi,serieComprobante:compRepository.serieComprobante,identificacionComprador:compRepository.identificacionComprador,codDoc:compRepository.codDoc,docOrigen:compRepository.docOrigen,fechaEmision:compRepository.fechaEmision,observacion:compRepository.observacion,codigoPorcentaje:compRepository.codigoPorcentaje,totalSinImpuestos:compRepository.totalSinImpuestos,totalDescuento:compRepository.totalDescuento,totalConImpuestos:compRepository.totalConImpuestos,propina:compRepository.propina,importeTotal:compRepository.importeTotal},cliente:{idCliente:clienteRepository.idCliente,nombreComercial:clienteRepository.nombreComercial,nombreFiscal:clienteRepository.nombreFiscal,numeroIdentificacion:clienteRepository.numeroIdentificacion,direccion:clienteRepository.direccion},detalles:detalleRepository,historial:historialRepository,infoAdicionalDocumento:infoAdicionalDocumento,datosAdicionalesArticulo:datosAdicionalesArticulo.map(item=>({idDocumento:item.idDocumento,idHistoryInfoAdicional:item.idHistoryInfoAdicional,idArticulo:item.idArticulo,idEtiqueta:item.idEtiqueta,idInfoAdicional:item.idInfoAdicional,jsonAdicional:JSON.parse(item.jsonAdicional),selected:item.selected,estado:item.estado}))}}}).catch(error=>{throw error})},save:function(data){return mS.getData("post",url+"Insert",data,!0).then(response=>response).catch(error=>{throw console.log("Error insert Aprob. Docs service",error),error})},update:function(id,data){return mS.getData("put",url+"Update/"+id,data,!0).then(response=>response).catch(error=>{throw console.log("Error update Aprob. Docs service",error),error})},detalleMapperFrom:function({detalles:detalles,fS:fS,decimal:decimal,findForSale:findForSale}){let enumeracion=1;for(let item of detalles){item.enumeracion=enumeracion++,item.valorDescuento=item.descuento,item.ice=0,item.nota=null;let subTotal=item.cantidad*item.precioUnitario;item.totalDescuento=fS.roundNumber(item.totalDescuento,decimal.nroDescuentoDetalle),item.subTotal=fS.roundNumber(subTotal,5),item.total=fS.roundNumber(item.precioTotalSinImpuesto,decimal.nroTotalDetalle),findForSale({idArticulo:item.idArticulo}).then(response=>{console.log(response);let{articulo:articulo,medidas:medidas,datosAdicionalesArticulo:datosAdicionalesArticulo}=response;item.medidas=medidas,item.datosAdicionalesArticulo=datosAdicionalesArticulo;let dataMedida=medidas.find(m=>m.idMedida===item.idMedida)||{};item.articuloTarifas=JSON.parse(dataMedida.tarifas)})}return console.log(detalles),detalles}};return service}))}(window.angular);